{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required case fields")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not isinstance(required_symbols, list):
        raise ValueError("invalid case field types")
    if not nodes:
        raise ValueError("case must contain nodes")

    required = set()
    for symbol in required_symbols:
        if not isinstance(symbol, str):
            raise ValueError("required symbols must be strings")
        required.add(symbol)

    fields = ("id", "parent", "symbol", "depth", "removable", "utility")
    normalized = []
    ids = set()
    positions = {}

    for position, node in enumerate(nodes):
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        if any(field not in node for field in fields):
            raise ValueError("node missing required field")

        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]

        if not isinstance(node_id, str) or node_id in ids:
            raise ValueError("node IDs must be unique strings")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("parent must be null or a string")
        if not isinstance(symbol, str):
            raise ValueError("node symbols must be strings")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("depth must be a nonnegative integer")
        if not isinstance(removable, bool):
            raise ValueError("removable must be boolean")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)):
            raise ValueError("utility must be numeric")
        if isinstance(utility, float) and not math.isfinite(utility):
            raise ValueError("utility must be finite")

        ids.add(node_id)
        positions[node_id] = position
        normalized.append((node_id, parent, symbol, depth, removable))

    roots = [node_id for node_id, parent, _, _, _ in normalized if parent is None]
    if len(roots) != 1:
        raise ValueError("tree must have exactly one root")

    by_id = {node_id: item for node_id, *item in normalized}
    children = {node_id: [] for node_id in ids}
    for node_id, parent, symbol, depth, removable in normalized:
        if parent is not None:
            if parent not in ids:
                raise ValueError("parent must reference an existing node")
            children[parent].append(node_id)
            parent_depth = by_id[parent][2]
            if depth != parent_depth + 1:
                raise ValueError("depth does not match parentage")

    visited = set()
    active = set()

    def visit(node_id):
        if node_id in active:
            raise ValueError("tree contains a cycle")
        if node_id in visited:
            return
        active.add(node_id)
        for child_id in children[node_id]:
            visit(child_id)
        active.remove(node_id)
        visited.add(node_id)

    visit(roots[0])
    if len(visited) != len(ids):
        raise ValueError("tree must be connected")

    retained = set(ids)
    removed = []
    candidates = sorted(
        normalized,
        key=lambda item: (-item[3], item[0])
    )

    for node_id, parent, symbol, depth, removable in candidates:
        if not removable or node_id not in retained:
            continue
        if not children[node_id] or not any(child in retained for child in children[node_id]):
            remaining_symbols = {
                item[2] for item in normalized if item[0] in retained and item[0] != node_id
            }
            if required.issubset(remaining_symbols):
                retained.remove(node_id)
                removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained),
    }"}
